from pathlib import Path
import json,base64
p=Path(__file__).parent
images={x.stem:'data:image/png;base64,'+base64.b64encode(x.read_bytes()).decode() for x in (p/'derivees').glob('*.png')}
t='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Méga-Tsareena — audit et essais</title><style>
*{box-sizing:border-box}body{background:#101b19;color:#edf5e7;font:16px system-ui,sans-serif;margin:0}main{max-width:1040px;padding:24px;margin:auto}h1{margin:0 0 6px}h2{font-size:1.2rem}.muted{color:#afc6b5}.badge{background:#dff6a8;color:#24391b;padding:5px 10px;border-radius:20px;font-weight:700;font-size:.8rem}.box{background:#1a2b26;border:1px solid #304d3c;border-radius:16px;padding:18px;margin-top:20px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.card{background:#d3e3c6;border-radius:12px;color:#243322;text-align:center;padding:4px}.card img{width:100%;height:160px;object-fit:contain;image-rendering:pixelated}.card small{display:block;padding:4px}button{background:#335744;color:white;border:1px solid #6b9676;border-radius:9px;padding:9px 12px;margin:3px;cursor:pointer;font-weight:600}button:hover,button.active{background:#b8d98b;color:#183021}#scene{height:260px;background:repeating-linear-gradient(45deg,#c6d9b8 0 24px,#d3e3c6 24px 48px);border-radius:12px;position:relative;overflow:hidden}#perso{position:absolute;left:50%;top:50%;width:160px;height:180px;object-fit:contain;image-rendering:pixelated;transform:translate(-50%,-50%)}#ombre{position:absolute;width:80px;height:20px;border-radius:50%;background:#58745444;left:50%;top:calc(50% + 75px);transform:translate(-50%,-50%)}.buttons{text-align:center;margin:10px}p,li{line-height:1.5}@media(max-width:600px){main{padding:16px}.grid{grid-template-columns:repeat(2,1fr)}}
</style></head><body><main><span class="badge">REPRISE · ESSAIS, PAS UN PACK FINAL</span><h1>Méga-Tsareena</h1><div class="muted">Audit des proportions, yeux et premiers essais d’action</div><section class="box"><h2>Huit vues à hauteur égale</h2><p>Le profil droit a été repris pour réduire la forme blanche saillante à la hanche. Le profil gauche montré ici est un <strong>miroir provisoire</strong> du droit : la génération gauche s’était retournée. La face et les trois-quarts ont des yeux plus lisibles.</p><div class="grid" id="vues"></div><p class="muted">Les vues arrière proviennent de l’ancien contrôle réduit : elles ne sont pas de nouveaux dessins. La face a changé de pose et la forme blanche reste plus marquée de face ; les couleurs et détails ne sont pas encore uniformes entre vues.</p></section><section class="box"><h2>Banc d’essai</h2><div id="scene"><div id="ombre"></div><img id="perso" alt="Méga-Tsareena"></div><div class="buttons" id="dirs"></div><div class="buttons" id="actions"><button data-action="idle">Lévitation</button><button data-action="sleep">Sommeil</button><button data-action="attack">Attaque</button><button data-action="hurt">Blessure</button></div><p class="muted">Actions disponibles de face uniquement : sommeil = une pose avec léger flottement ; attaque et blessure = alternance de deux poses. Les jambes et les bras restent immobiles. Ce sont des essais visuels, pas des animations SpriteCollab complètes ni une simulation de transformation.</p></section><section class="box"><h2>À terminer</h2><ul><li>Unifier la silhouette, la forme blanche des hanches et les yeux dans chaque direction, sans perdre la pose de référence.</li><li>Créer les véritables images intermédiaires pour chaque action et chacune des huit directions, puis les planches, durées et points d’ancrage SpriteCollab.</li><li>Recréer la transformation et les autres actions de donjon. Les fichiers de la simulation antérieure ne sont plus présents : seuls le contrôle réduit et les références conservées ont servi ici.</li></ul></section></main><script>
const sprites=__DATA__;const names=['face','avant-droite','droite','arriere-droite','dos','arriere-gauche','gauche','avant-gauche'];const labels=['Face','Avant droite','Droite','Arrière droite','Dos','Arrière gauche','Gauche · miroir','Avant gauche'];const views=document.querySelector('#vues'),dirs=document.querySelector('#dirs'),img=document.querySelector('#perso');let dir='face',action='idle',since=performance.now();names.forEach((n,i)=>{let c=document.createElement('div');c.className='card';let pic=document.createElement('img');pic.src=sprites[n];pic.alt=labels[i];let txt=document.createElement('small');txt.textContent=labels[i];c.append(pic,txt);views.append(c);let b=document.createElement('button');b.textContent=labels[i];b.onclick=()=>{dir=n;action='idle';since=performance.now();refresh()};dirs.append(b)});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{dir='face';action=b.dataset.action;since=performance.now();refresh()});function refresh(){[...dirs.children].forEach((b,i)=>b.classList.toggle('active',names[i]===dir));document.querySelectorAll('[data-action]').forEach(b=>b.classList.toggle('active',b.dataset.action===action))}function tick(t){let dt=t-since,frame=dir;if(action==='sleep')frame='sommeil';if(action==='attack')frame=(dt%1600<750?'face':'attaque');if(action==='hurt')frame=(dt%1200<650?'face':'blessure');let src=sprites[frame];if(img.src!==src)img.src=src;img.style.transform=`translate(-50%,calc(-50% + ${Math.sin(t/500)*3}px))`;requestAnimationFrame(tick)}refresh();requestAnimationFrame(tick);
</script></body></html>'''
(p/'Audit-et-essais.html').write_text(t.replace('__DATA__',json.dumps(images,separators=(',',':'))),encoding='utf8')
